import type { Metadata } from "next";

import { SITE_URL, siteUrl } from "@/lib/site-url";

/** The site-wide link-preview image, generated by src/app/opengraph-image.tsx. */
const SHARE_IMAGE = "/opengraph-image";

/**
 * Metadata for a public-site subpage: the root layout's template turns `title`
 * into "<title> | Fabric", and the canonical and og:url name the www host
 * (decision M1). A page's own `openGraph` replaces the parent's, so the
 * file-based share image isn't inherited and is named here instead.
 */
export function sitePageMetadata({
  path,
  title,
  description,
}: {
  path: string;
  title: string;
  description: string;
}): Metadata {
  const url = siteUrl(path);
  return {
    metadataBase: new URL(SITE_URL),
    title,
    description,
    alternates: { canonical: url },
    openGraph: {
      type: "website",
      url,
      siteName: "Fabric",
      title: `${title} | Fabric`,
      description,
      images: [SHARE_IMAGE],
    },
    twitter: {
      card: "summary_large_image",
      title: `${title} | Fabric`,
      description,
      images: [SHARE_IMAGE],
    },
  };
}
